package dev.veltraph.client.garden.admission;
import org.junit.jupiter.api.Test;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.garden.admission.GardenThresholdAdmission.Result.*;
import static dev.veltraph.client.garden.admission.GardenAdmissionSelection.*;
class GardenAdmissionSelectionTest {
    @Test void admittedVisitorPreventsEveryLowerFamilyQuery(){var calls=new AtomicInteger();var d=choose(true,()->ADMIT,false,()->{calls.incrementAndGet();return ADMIT;},false);assertEquals(Family.VISITOR,d.family());assertEquals(State.ADMIT,d.state());assertEquals(0,calls.get());}
    @Test void unsupportedVisitorInstantKeepsSelectedFamilyAndNeverSubstitutesPest(){var calls=new AtomicInteger();var d=choose(true,()->ADMIT,true,()->{calls.incrementAndGet();return ADMIT;},false);assertEquals(Family.VISITOR,d.family());assertEquals(State.UNSUPPORTED_INSTANT,d.state());assertEquals(0,calls.get());}
    @Test void pestInstantUnsupportedCannotAppearAdmitted(){var d=choose(false,()->{fail("Disabled visitor must not evaluate");return ADMIT;},false,()->ADMIT,true);assertEquals(Family.PEST,d.family());assertEquals(State.UNSUPPORTED_INSTANT,d.state());}
    @Test void disabledVisitorAllowsAuthenticPestOnlyMappingWithoutVisitorRng(){var visitorCalls=new AtomicInteger();var pestCalls=new AtomicInteger();var d=choose(false,()->{visitorCalls.incrementAndGet();return COUNT_UNKNOWN;},true,()->{pestCalls.incrementAndGet();return ADMIT;},false);assertEquals(Family.PEST,d.family());assertEquals(0,visitorCalls.get());assertEquals(1,pestCalls.get());}
    @Test void enabledUnknownVisitorCannotBeTreatedAsFalse(){for(var unknown:new GardenThresholdAdmission.Result[]{COUNT_UNKNOWN,CAPABILITY_UNKNOWN,THRESHOLD_UNKNOWN,READINESS_UNKNOWN}){var calls=new AtomicInteger();var d=choose(true,()->unknown,false,()->{calls.incrementAndGet();return ADMIT;},false);assertEquals(Family.NONE,d.family());assertEquals(State.UNKNOWN_PRIORITY,d.state());assertEquals(0,calls.get());}}
    @Test void knownVisitorDenialAllowsOnlyThenPestEvaluation(){for(var denied:new GardenThresholdAdmission.Result[]{NOT_READY,BELOW_THRESHOLD,DISABLED,CAPABILITY_DENIED,CONTEST_DENIED}){var calls=new AtomicInteger();var d=choose(true,()->denied,false,()->{calls.incrementAndGet();return ADMIT;},false);assertEquals(Family.PEST,d.family());assertEquals(1,calls.get());}}
    @Test void lowerThresholdRngIsNeverDrawnAfterVisitorAdmission(){var draws=new AtomicInteger();var d=choose(true,()->GardenThresholdAdmission.visitor(4,true,()->{draws.incrementAndGet();return 3;},true,true,false,true),false,()->GardenThresholdAdmission.pest(4,()->{draws.addAndGet(100);return 3;},true,true,true,false,true),false);assertEquals(Family.VISITOR,d.family());assertEquals(1,draws.get());}
    @Test void deferredFamilyCannotChangeOrSubstituteOnPolicyOrEvidenceRecheck(){assertTrue(sameAdmittedFamily(Family.VISITOR,new Decision(Family.VISITOR,State.ADMIT,ADMIT)));assertFalse(sameAdmittedFamily(Family.VISITOR,new Decision(Family.PEST,State.ADMIT,ADMIT)));assertFalse(sameAdmittedFamily(Family.PEST,new Decision(Family.VISITOR,State.ADMIT,ADMIT)));assertFalse(sameAdmittedFamily(Family.VISITOR,new Decision(Family.VISITOR,State.UNSUPPORTED_INSTANT,ADMIT)));assertFalse(sameAdmittedFamily(Family.NONE,new Decision(Family.NONE,State.DENIED,NOT_READY)));}
    @Test void nativeCapabilitySupplierNeverRunsForAdmittedVisitor(){var calls=new AtomicInteger();choose(true,()->ADMIT,false,()->{calls.incrementAndGet();return CAPABILITY_DENIED;},false);assertEquals(0,calls.get());}
}
